+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest {
+
+    static Playwright playwright;
+    static Browser browser;
+
+    @LocalServerPort
+    int port;
+
+    @BeforeAll
+    static void start() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stop() {
+        browser.close();
+        playwright.close();
+    }
+
+    private Locator field(Page page, String label) {
+        return page.getByLabel(label, new Page.GetByLabelOptions().setExact(true));
+    }
+
+    @Test
+    void fullFlow() {
+        Page page = browser.newPage();
+        page.navigate("http://localhost:" + port + "/contact");
+        page.locator("h1:has-text('Contact')").waitFor();
+        Locator send = page.locator("vaadin-button:has-text('Send')");
+
+        send.click();
+        page.locator("vaadin-text-field[invalid]").first().waitFor();
+        page.getByText("Name is required").waitFor();
+        page.getByText("Give an e-mail address or a phone number").waitFor();
+
+        field(page, "Name").fill("Ann");
+        field(page, "Email").fill("bad");
+        field(page, "Message").fill("Hello there");
+        send.click();
+        page.getByText("Enter a valid e-mail address").waitFor();
+
+        field(page, "Email").fill("ann@example.com");
+        field(page, "Name").press("Enter");
+        page.locator("vaadin-notification-card:has-text('Message sent')").waitFor();
+        page.locator("vaadin-grid-cell-content:has-text('Hello there')").waitFor();
+        assertEquals("", field(page, "Name").inputValue());
+        assertTrue(send.isDisabled() || send.getAttribute("disabled") != null);
+        field(page, "Phone").pressSequentially("1");
+        page.waitForCondition(() -> send.getAttribute("disabled") == null);
+
+        page.locator("a:has-text('About')").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertEquals("1", field(page, "Phone").inputValue());
+        page.locator("a:has-text('About')").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        page.locator("h1:has-text('About')").waitFor();
+
+        page.locator("a:has-text('Contact')").click();
+        page.locator("vaadin-grid-cell-content:has-text('Hello there')").waitFor();
+        page.locator("a:has-text('About')").click();
+        page.locator("h1:has-text('About')").waitFor();
+        assertEquals(0, page.locator("vaadin-dialog-overlay[opened]").count());
+    }
